import csv
t1='47f1370e-62d8-56c6-8ae6-d34fa69cf177'
t2='03f8d175-8f4f-5a5c-8017-4cac0978dde8'
ts='2018-01-17T11:00:00'
def val(tid):
    with open(VALUES_CSV) as f:
        for r in csv.DictReader(f):
            if r['timeseries_id']==tid:
                t=r['timestamp'].replace(' ','T')[:19]
                if t==ts:
                    return float(r['value'])
    return None
